// Package sounds synthesizes notifier's notification sounds. notifyd
// writes them out at start-up; the Android app bundles the same bytes,
// generated by ./gen.
package sounds

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"math"
	"os"
	"path/filepath"
)

// Names are the sounds: an ordinary message, a high-priority one, and a
// question waiting for an answer.
var Names = []string{"message", "urgent", "question"}

const (
	rate = 44100
	peak = 0.7079     // −3 dBFS
	fade = rate / 200 // samples (5 ms), against clicks at either end
)

// tone is one struck note: partials are relative amplitudes of the
// harmonics, and glide multiplies the pitch by the end of the note.
type tone struct {
	at, freq, length, gain, glide float64
	partials                      []float64
	sustain                       bool // hold the level instead of decaying
}

var (
	soft = []float64{1, 0.25, 0.08}
	// Strong odd harmonics: close to a square wave, harsh and hard to ignore.
	harsh = []float64{1, 0, 0.6, 0, 0.4, 0, 0.28, 0, 0.2}
)

const (
	b5 = 987.77
	c5 = 523.25
	e5 = 659.26
	g5 = 783.99
	a5 = 880.00
	e6 = 1318.51
)

var scores = map[string][]tone{
	"message": {
		{at: 0, freq: e5, length: 0.30, gain: 0.8, glide: 1, partials: soft},
		{at: 0.12, freq: a5, length: 0.33, gain: 1, glide: 1, partials: soft},
	},
	// Three quick bursts of a high–low alternation, harsh and sustained
	// like an alarm.
	"urgent": urgent(),
	"question": {
		{at: 0, freq: c5, length: 0.24, gain: 0.85, glide: 1, partials: soft},
		{at: 0.17, freq: g5, length: 0.43, gain: 1, glide: 1.12, partials: soft},
	},
}

func urgent() []tone {
	var score []tone
	for burst := range 3 {
		for i := range 4 {
			freq := e6
			if i%2 == 1 {
				freq = b5
			}
			at := float64(burst)*0.45 + float64(i)*0.085
			score = append(score, tone{at: at, freq: freq, length: 0.085, gain: 1, glide: 1, partials: harsh, sustain: true})
		}
	}
	return score
}

// WAV returns sound [name] as a 16-bit mono PCM WAV file. The same name
// always gives the same bytes.
func WAV(name string) ([]byte, error) {
	score, ok := scores[name]
	if !ok {
		return nil, fmt.Errorf("no sound %q", name)
	}
	return encode(render(score)), nil
}

func render(score []tone) []float64 {
	var end float64
	for _, t := range score {
		end = max(end, t.at+t.length)
	}
	out := make([]float64, int(end*rate))
	for _, t := range score {
		start := int(t.at * rate)
		n := int(t.length * rate)
		decay := t.length / 5
		phase := 0.0
		for i := 0; i < n && start+i < len(out); i++ {
			s := float64(i) / rate
			// Exponential pitch glide; the phase integrates the frequency.
			phase += 2 * math.Pi * t.freq * math.Pow(t.glide, s/t.length) / rate
			attack := min(s/0.004, 1)
			env := attack * t.gain
			if t.sustain {
				env *= min((t.length-s)/0.004, 1)
			} else {
				env *= math.Exp(-s / decay)
			}
			var v float64
			for h, a := range t.partials {
				v += a * math.Sin(float64(h+1)*phase)
			}
			out[start+i] += env * v
		}
	}
	var top float64
	for _, v := range out {
		top = max(top, math.Abs(v))
	}
	ramp := fade
	for i := range out {
		g := peak / top
		if i < ramp {
			g *= float64(i) / float64(ramp)
		}
		if j := len(out) - 1 - i; j < ramp {
			g *= float64(j) / float64(ramp)
		}
		out[i] *= g
	}
	return out
}

func encode(samples []float64) []byte {
	var b bytes.Buffer
	data := uint32(len(samples) * 2)
	w := func(v any) { _ = binary.Write(&b, binary.LittleEndian, v) }
	b.WriteString("RIFF")
	w(36 + data)
	b.WriteString("WAVEfmt ")
	w(uint32(16))
	w(uint16(1)) // PCM
	w(uint16(1)) // mono
	w(uint32(rate))
	w(uint32(rate * 2))
	w(uint16(2))
	w(uint16(16))
	b.WriteString("data")
	w(data)
	for _, v := range samples {
		w(int16(math.Round(v * math.MaxInt16)))
	}
	return b.Bytes()
}

// Install writes the sounds into dir as <name>.wav, rewriting a file only
// when it differs, and returns their paths by name.
func Install(dir string) (map[string]string, error) {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	paths := map[string]string{}
	for _, name := range Names {
		data, err := WAV(name)
		if err != nil {
			return nil, err
		}
		path := filepath.Join(dir, name+".wav")
		if old, err := os.ReadFile(path); err != nil || !bytes.Equal(old, data) {
			// Renamed into place, so a notification never plays half a file.
			tmp := path + ".tmp"
			if err := os.WriteFile(tmp, data, 0o644); err != nil {
				return nil, err
			}
			if err := os.Rename(tmp, path); err != nil {
				return nil, err
			}
		}
		paths[name] = path
	}
	return paths, nil
}
